/* --- L.Icon.FontAwesome.css --- */
.leaflet-fa-markers {
  position: absolute;
  left: 0;
  top: 0;
  display: block;
  text-align: center;
  margin-left: -15px;
  margin-top: -50px;
  width: 30px;
  height: 50px;
}

.leaflet-fa-markers .marker-icon-svg {
  position: absolute;
}

.leaflet-fa-markers .icon-container{
  position: absolute;
  top: 8px;
  /*left: calc(-50% + 1px);*/
  /*right: -50%;*/
  width: 32px;
}

.leaflet-fa-markers .feature-icon {
  font-size: 12px;
  line-height: 0px;
  display: inline-block;
}
/* --- osm-map-elementor.css --- */
.marker-description{
    white-space: pre-line;
}
/* --- dynamic-visibility.css --- */
.dce-visibility-element-hidden,
.dce-visibility-widget-hidden,
.dce-visibility-column-hidden,
.dce-visibility-section-hidden {
  display: none !important;
}

.dce-visibility-element-hidden.elementor-widget-dyncontel-panorama {
  display: block;
  position: fixed;
  left: 10000px;
}

/* --- style.css --- */
.loader {
    border: 16px solid #f3f3f3 ; /* Light grey */
    border-top: 16px solid #3498db ; /* Blue */
    border-radius: 50% ;
    width: 120px ;
    height: 120px;
    animation: spin 2s linear infinite ;
    margin: auto;
    display: none;
}

.flex {
    width: 100% ;
    display: flex ;
    flex-wrap: wrap;
}

.imagen, .no-loader {
    flex: 1 0 50%;
}

@keyframes spin {
    0% {
        transform: rotate(0deg);
    }
    100% {
        transform: rotate(360deg);
    }
}

.principal {
    display: flex !important;
    flex-wrap: wrap !important;
}

@media only screen and (max-width: 998px) {
    .principal {
        width: 100% !important;
        flex-direction: column !important;
        align-content: space-around !important;
        align-items: center !important;
    }
}

/*Metodos de pago*/
.payment-method {
    margin: 0 0 20px 0 !important;
}

.payment-method h3 {
    font-size: 18px !important;
    font-weight: bold !important;
    margin: 0 0 10px 0 !important;
}

.payment-method ul {
    list-style: none !important;
    margin: 0 0 0 0 !important;
    padding: 0 0 0 0 !important;
}

.payment-method li {
    margin: 0 0 10px 0 !important;
}

.payment-method a {
    display: block !important;
    font-size: 16px !important;
    line-height: 20px !important;
    color: white !important;
    text-decoration: none !important;
    cursor: pointer !important;
    background-color: #27337e !important;
    padding: 2% 0% !important;
    padding-left: 2% !important;
    border-radius: 5px !important;
    text-align: center !important;
}

.payment-method .payment-form {
    padding-left: 5% !important;
    padding-right: 5% !important;
}

.inputtxt {
    display: block !important;
    width: 100% !important;
    padding: 0.375rem 0.75rem !important;
    font-size: 1rem !important;
    font-weight: 400 !important;
    line-height: 1.5 !important;
    color: #495057 !important;
    background-color: #fff !important;
    background-clip: padding-box !important;
    border: 1px solid #ced4da !important;
    border-radius: 0.25rem !important;
    transition: border-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out !important;
}

.inputtxt:focus {
    color: #495057 !important;
    background-color: #fff !important;
    border-color: #80bdff !important;
    outline: 0 !important;
    box-shadow: 0 0 0 0.2rem rgba(0, 123, 255, 0.25) !important;
}

.selecttxt {
    display: block !important;
    width: 100% !important;
    padding: 0.375rem 0.75rem !important;
    font-size: 1rem !important;
    font-weight: 400 !important;
    line-height: 1.5 !important;
    color: #495057 !important;
    background-color: #fff !important;
    background-image: none !important;
    background-clip: padding-box !important;
    border: 1px solid #ced4da !important;
    border-radius: 0.25rem !important;
    transition: border-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out !important;
}

.selecttxt:focus {
    color: #495057 !important;
    background-color: #fff !important;
    border-color: #80bdff !important;
    outline: 0 !important;
    box-shadow: 0 0 0 0.2rem rgba(0, 123, 255, 0.25) !important;
}

.selecttxt::-ms-expand {
    display: none !important;
}

.alert {
    padding: 15px !important;
    margin-bottom: 20px !important;
    border: 1px solid transparent !important;
    border-radius: .25rem !important;
}

.alert-primary {
    color: #005ce8 !important;
    background-color: #fff7fb !important;
    border-color: #005ce8 !important;
}
.boton {
    width: 100% !important;
    margin-top: 20px !important;
    background-color: #004987 !important;
    border: 1px solid #004987 !important;
    border-radius: 5px !important;
    display: inline-block !important;
    padding: 0.5rem 1rem !important;
    color: white !important;
    font-size: 1rem !important;
    font-weight: 400 !important;
    line-height: 1.5 !important;
    text-align: center !important;
    white-space: nowrap !important;
    vertical-align: middle !important;
    -webkit-user-select: none !important;
    -moz-user-select: none !important;
    -ms-user-select: none !important;
    user-select: none !important;
    transition: color 0.15s ease-in-out, background-color 0.15s ease-in-out, border-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out !important;
    cursor: pointer !important;
}

.mt-top{
    margin-top: 12px;
}
/* --- styles.css --- */
.wpcf7 .screen-reader-response {
	position: absolute;
	overflow: hidden;
	clip: rect(1px, 1px, 1px, 1px);
	clip-path: inset(50%);
	height: 1px;
	width: 1px;
	margin: -1px;
	padding: 0;
	border: 0;
	word-wrap: normal !important;
	word-break: normal !important;
}

.wpcf7 .hidden-fields-container {
	display: none;
}

.wpcf7 form .wpcf7-response-output {
	margin: 2em 0.5em 1em;
	padding: 0.2em 1em;
	border: 2px solid #00a0d2; /* Blue */
}

.wpcf7 form.init .wpcf7-response-output,
.wpcf7 form.resetting .wpcf7-response-output,
.wpcf7 form.submitting .wpcf7-response-output {
	display: none;
}

.wpcf7 form.sent .wpcf7-response-output {
	border-color: #46b450; /* Green */
}

.wpcf7 form.failed .wpcf7-response-output,
.wpcf7 form.aborted .wpcf7-response-output {
	border-color: #dc3232; /* Red */
}

.wpcf7 form.spam .wpcf7-response-output {
	border-color: #f56e28; /* Orange */
}

.wpcf7 form.invalid .wpcf7-response-output,
.wpcf7 form.unaccepted .wpcf7-response-output,
.wpcf7 form.payment-required .wpcf7-response-output {
	border-color: #ffb900; /* Yellow */
}

.wpcf7-form-control-wrap {
	position: relative;
}

.wpcf7-not-valid-tip {
	color: #dc3232; /* Red */
	font-size: 1em;
	font-weight: normal;
	display: block;
}

.use-floating-validation-tip .wpcf7-not-valid-tip {
	position: relative;
	top: -2ex;
	left: 1em;
	z-index: 100;
	border: 1px solid #dc3232;
	background: #fff;
	padding: .2em .8em;
	width: 24em;
}

.wpcf7-list-item {
	display: inline-block;
	margin: 0 0 0 1em;
}

.wpcf7-list-item-label::before,
.wpcf7-list-item-label::after {
	content: " ";
}

.wpcf7-spinner {
	visibility: hidden;
	display: inline-block;
	background-color: #23282d; /* Dark Gray 800 */
	opacity: 0.75;
	width: 24px;
	height: 24px;
	border: none;
	border-radius: 100%;
	padding: 0;
	margin: 0 24px;
	position: relative;
}

form.submitting .wpcf7-spinner {
	visibility: visible;
}

.wpcf7-spinner::before {
	content: '';
	position: absolute;
	background-color: #fbfbfc; /* Light Gray 100 */
	top: 4px;
	left: 4px;
	width: 6px;
	height: 6px;
	border: none;
	border-radius: 100%;
	transform-origin: 8px 8px;
	animation-name: spin;
	animation-duration: 1000ms;
	animation-timing-function: linear;
	animation-iteration-count: infinite;
}

@media (prefers-reduced-motion: reduce) {
	.wpcf7-spinner::before {
		animation-name: blink;
		animation-duration: 2000ms;
	}
}

@keyframes spin {
	from {
		transform: rotate(0deg);
	}

	to {
		transform: rotate(360deg);
	}
}

@keyframes blink {
	from {
		opacity: 0;
	}

	50% {
		opacity: 1;
	}

	to {
		opacity: 0;
	}
}

.wpcf7 [inert] {
	opacity: 0.5;
}

.wpcf7 input[type="file"] {
	cursor: pointer;
}

.wpcf7 input[type="file"]:disabled {
	cursor: default;
}

.wpcf7 .wpcf7-submit:disabled {
	cursor: not-allowed;
}

.wpcf7 input[type="url"],
.wpcf7 input[type="email"],
.wpcf7 input[type="tel"] {
	direction: ltr;
}

.wpcf7-reflection > output {
	display: list-item;
	list-style: none;
}

.wpcf7-reflection > output[hidden] {
	display: none;
}

